'use strict';
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict'),{createHash}=require('node:crypto');
require('./deny-network.cjs');
const repo=path.resolve(__dirname,'../../..'),base='.artifacts/deep-audit-round2-preview-lifecycle-fix';
const bytes=p=>fs.readFileSync(path.join(repo,p)),text=p=>bytes(p).toString('utf8'),json=p=>JSON.parse(text(p).replace(/^\uFEFF/,'')),sha=b=>createHash('sha256').update(b).digest('hex');
const frozen=json(base+'/snapshot/frozen.json');for(const f of frozen.frozen)assert.equal(sha(bytes(f.path)),f.sha256,f.path);
const old='.artifacts/deep-audit-round2-preview',oldFreeze=json(old+'/evidence-freeze.json');for(const f of [...oldFreeze.evidence,...oldFreeze.sidecars])assert.equal(sha(bytes(old+'/'+f.path)),f.sha256,'Original red changed '+f.path);
const beforeSource=text(base+'/snapshot/before/renderer/right-workspace-integration.js'),afterSource=text(base+'/snapshot/after/renderer/right-workspace-integration.js');assert.equal(sha(beforeSource),frozen.beforeSource);assert.equal(afterSource,text('renderer/right-workspace-integration.js'));
const span=(s,a,b)=>{const start=s.indexOf(a),end=s.indexOf(b,start+a.length);assert.ok(start>=0&&end>start);return s.slice(start,end)};
const invariantRegions=[['  function safePreviewSource(', '  function documentOpenAction('],['  function documentOpenAction(', '  function renderDocument('],['  function isCurrentDocumentRequest(', '  async function openDocument('],['  async function openDocument(', '  async function openLocalDocument('],['  async function openLocalDocument(', '  function scheduleDraft('],['  let modelPreview = null','  window.harnessDesktopRightWorkspace = Object.freeze(']].map(([start,end])=>{const a=span(beforeSource,start,end),b=span(afterSource,start,end);assert.equal(a,b,start);return {start,end,sha256:sha(a),byteIdentical:true}});
const runs=['before-final','after-final'].map(run=>{const root=base+'/'+run,receipt=json(root+'/receipt.json'),summary=json(root+'/summary.json'),manifest=json(root+'/input-manifest.json');assert.equal(sha(bytes(root+'/receipt.json')),summary.receiptSha256);assert.equal(receipt.checks.length,48);assert.deepEqual(receipt.nativeAttempts,[]);assert.deepEqual(receipt.nodeNetworkAttempts,[]);assert.deepEqual(receipt.blockedRequests,[]);assert.deepEqual(receipt.navigation,[]);assert.equal(summary.passed,receipt.checks.filter(c=>c.pass).length);for(const [p,hash] of Object.entries(manifest.inputs))assert.equal(sha(bytes(p)),hash,p);return {run,summary,trace:json(root+'/lifecycle-trace.json'),protocolCalls:receipt.protocolCalls.length,nativeAttempts:0,nodeNetworkAttempts:0,networkFallback:0,navigationGuard:0,inputs:manifest.inputs}});
assert.equal(runs[0].summary.passed,42);assert.equal(runs[1].summary.passed,48);assert.equal(runs[0].summary.extensionSha256,runs[1].summary.extensionSha256);assert.equal(runs[0].summary.originalAssertionSectionSha256,runs[1].summary.originalAssertionSectionSha256);assert.equal(sha(bytes('tests/fixtures/deep-audit-preview-lifecycle-fix/scenarios.js.txt')),runs[0].summary.extensionSha256);
for(const [p,hash] of Object.entries(runs[0].inputs))if(!p.includes('/snapshot/before/'))assert.equal(runs[1].inputs[p],hash,'Shared source changed '+p);
for(const name of ['renderer.js','interactive.html','deny-network.cjs'])assert.equal(sha(bytes('tests/fixtures/deep-audit-preview-lifecycle-fix/'+name)),sha(bytes('tests/fixtures/deep-audit-preview-components/'+name)),name);
const result={runs,invariantRegions,oldEvidenceDrift:[],sharedInputsIdentical:true,immutableFixturesIdentical:true};
const output=base+'/verification.json';if(process.argv.includes('--check')){assert.deepEqual(json(output),result)}else{assert.ok(!fs.existsSync(path.join(repo,output)));fs.writeFileSync(path.join(repo,output),JSON.stringify(result,null,2))};console.log(JSON.stringify({before:runs[0].summary.passed,after:runs[1].summary.passed,total:48,protocolCalls:runs.map(r=>r.protocolCalls),invariantRegions:invariantRegions.length,oldDrift:[]},null,2));
